local RunService = game:GetService("RunService")
local LuaTypeProvider = require(script.Parent.Parent.DependencyInjection.LuaTypeProvider)

local HostingEnvironment = {}
HostingEnvironment.__index = HostingEnvironment

function HostingEnvironment.new(): IHostingEnvironment
	local self = setmetatable({}, HostingEnvironment)
	self.EnvironmentName = ""
	self.ApplicationName = ""
	self.ContentRootPath = ""
	if RunService:IsServer() then
		self.Context = "Server"
	else
		self.Context = "Client"
	end
	self.IsStudio = function()
		return RunService:IsStudio()
	end
	self.IsServer = function()
		return RunService:IsServer()
	end
	self.IsClient = function()
		return RunService:IsClient()
	end

	return self
end

function HostingEnvironment:MatchContext(context: "Server" | "Client" | nil | "")
	if context == nil then
		return true
	end
	return self.Context == context
end

function HostingEnvironment:UpdateProperty(name: string, value: any)
	if self[name] then
		error(string.format("Property %s already exists in HostingEnvironment", name))
	end
	self[name] = value
end

return HostingEnvironment
